with lines as (select id, customer_id, created_at, coupon_codes, inline(items) from carts) select case when price >= 219 then 'LARGE' else 'SMALL' end as price_tier, case when product_id >= 11 then 'LARGE' else 'SMALL' end as product_id_tier, count(distinct promo) as distinct_promos, sum(case when promo = 'SPRING10' then qty else 0 end) as spring10_qty, count(*) as num_rows from lines group by grouping sets ((case when price >= 219 then 'LARGE' else 'SMALL' end, case when product_id >= 11 then 'LARGE' else 'SMALL' end), (case when price >= 219 then 'LARGE' else 'SMALL' end)) order by num_rows desc;
